function parseSlot(value:string){
 const v=value.trim();
 const twentyFour=v.match(/^(\d{2}):(\d{2})$/);
 if(twentyFour){
  const h=Number(twentyFour[1]); const min=Number(twentyFour[2]);
  return h>=0&&h<=23&&min>=0&&min<=59 ? h*60+min : NaN;
 }
 const m=v.match(/^(\d{1,2}):(\d{2})\s*(AM|PM)$/i); if(!m) return NaN;
 let h=Number(m[1]); const min=Number(m[2]); const ap=m[3].toUpperCase();
 if(h<1||h>12||min>59)return NaN;
 if(h===12)h=0; if(ap==='PM')h+=12; return h*60+min;
}
function rangeOf(value:string){ const parts=value.split(/\s*(?:—|–|-)\s*/); if(parts.length!==2)return null; const a=parseSlot(parts[0]),b=parseSlot(parts[1]); return Number.isFinite(a)&&Number.isFinite(b)&&b>a?{start:a,end:b}:null; }
function slotOverlaps(a:string,b:string){const x=rangeOf(a),y=rangeOf(b); return !!x&&!!y&&x.start<y.end&&y.start<x.end;}
const courtSlots=Array.from({length:15},(_,i)=>{const h=6+i;const f=(x:number)=>`${x%12||12}:00 ${x>=12?'PM':'AM'}`;return `${f(h)} — ${f(h+1)}`});

async function printReceipt(receipt:{business:string;customer:string;items:{name:string;qty:number;price:number}[];subtotal:number;discount:number;tax:number;total:number;paymentMethod:string;reference?:string}){
 const iframe=document.createElement('iframe'); iframe.style.position='fixed'; iframe.style.right='0'; iframe.style.bottom='0'; iframe.style.width='0'; iframe.style.height='0'; iframe.style.border='0';
 document.body.appendChild(iframe);
 const doc=iframe.contentDocument; if(!doc) return;
 const rows=receipt.items.map(i=>`<tr><td>${i.name}</td><td style="text-align:center">${i.qty}</td><td style="text-align:right">${(i.price*i.qty).toLocaleString()}</td></tr>`).join('');
 doc.open(); doc.write(`<!doctype html><html><head><title>${receipt.business} Receipt</title><style>@page{size:80mm auto;margin:4mm}body{font-family:Arial,sans-serif;width:72mm;margin:0;color:#111;font-size:12px}h1{font-size:17px;text-align:center;margin:0 0 3px}p{margin:3px 0}.muted{color:#666;font-size:10px}.rule{border-top:1px dashed #999;margin:8px 0}table{width:100%;border-collapse:collapse}td{padding:4px 0;vertical-align:top}.total{font-size:16px;font-weight:800}.center{text-align:center}</style></head><body><h1>ZAWANA</h1><div class="center"><b>${receipt.business}</b></div><p class="muted center">${new Date().toLocaleString()}</p><p>Customer: ${receipt.customer}</p><div class="rule"/><table>${rows}</table><div class="rule"/><table><tr><td>Subtotal</td><td style="text-align:right">${receipt.subtotal.toLocaleString()}</td></tr><tr><td>Discount</td><td style="text-align:right">-${receipt.discount.toLocaleString()}</td></tr><tr><td>Tax</td><td style="text-align:right">${receipt.tax.toLocaleString()}</td></tr><tr class="total"><td>Total</td><td style="text-align:right">${receipt.total.toLocaleString()} MMK</td></tr></table><div class="rule"/><p>Payment: <b>${receipt.paymentMethod}</b></p>${receipt.reference?`<p>Ref: ${receipt.reference}</p>`:''}<p class="center muted">Thank you for choosing Zawana.</p></body></html>`); doc.close();
 setTimeout(()=>{try{iframe.contentWindow?.focus();iframe.contentWindow?.print()}finally{setTimeout(()=>iframe.remove(),1500)}},150);
}

