function BadmintonCheckIn({notify}:{notify:(s:string)=>void}){
 const o=useOperations();
 const [enrollments,setEnrollments]=useState<any[]>([]); const [selected,setSelected]=useState<any>(null); const [packages,setPackages]=useState<any[]>([]);
 const [query,setQuery]=useState(''); const [loading,setLoading]=useState(true); const [busy,setBusy]=useState(false); const [purchase,setPurchase]=useState(false); const [renew,setRenew]=useState(false); const [packageId,setPackageId]=useState(''); const [paymentMethod,setPaymentMethod]=useState('Cash'); const [purchaseStudentId,setPurchaseStudentId]=useState(''); const [actionError,setActionError]=useState('');
 const load=async()=>{setLoading(true);try{const [e,p]=await Promise.all([get<any[]>('/badminton/enrollments'),get<any[]>('/packages/badminton')]);setEnrollments(e);setPackages(p);if(selected){const next=e.find(x=>x.id===selected.id);setSelected(next||null)}}catch(e:any){notify(e.message||'Could not load package members.')}finally{setLoading(false)}};
 useEffect(()=>{load()},[]);
 const filtered=enrollments.filter(x=>[x.studentName,x.phone,x.packageName].some((v:string)=>v.toLowerCase().includes(query.toLowerCase())));
 const students=o.students.filter((s:any)=>[s.name,s.phone,s.id].some((v:string)=>v.toLowerCase().includes(query.toLowerCase())));
 const selectedStudent=o.students.find((s:any)=>s.id===purchaseStudentId);
 const current=selected;
 const selectStudent=(id:string)=>setSelected(enrollments.find(x=>x.studentId===id)||null);
 const buy=async()=>{setActionError(''); const student=selectedStudent; if(!student){setActionError('Please select a student.');return} if(!packageId){setActionError('Please select an active badminton package.');return} setBusy(true); try{const created=await post<any>('/badminton/enrollments',{studentId:student.id,studentName:student.name,phone:student.phone||'',packageId,startDate:today,paymentMethod}); notify(`${student.name} package activated.`); setPurchase(false); setPurchaseStudentId(''); setPackageId(''); await load(); setSelected(created)} catch(e:any){const message=e?.message||'Could not activate package.'; setActionError(message); notify(message)} finally{setBusy(false)}};
 const doRenew=async()=>{setActionError(''); if(!current){setActionError('Select a package holder first.');return} if(!packageId){setActionError('Please select an active badminton package.');return} setBusy(true); try{const updated=await post<any>(`/badminton/enrollments/${current.id}/renew`,{packageId,startDate:today,paymentMethod}); notify(`${current.studentName} package renewed.`); setRenew(false); await load(); setSelected(updated)} catch(e:any){const message=e?.message||'Could not renew package.'; setActionError(message); notify(message)} finally{setBusy(false)}};
 const checkIn=async()=>{if(!current)return;setBusy(true);try{const r=await post<any>('/badminton/check-ins',{enrollmentId:current.id});notify(r.warning?`${current.studentName} checked in. Only ${r.enrollment.sessionsRemaining} sessions remain.`:`${current.studentName} checked in successfully.`);await load();setSelected((x:any)=>x?{...x,sessionsRemaining:r.enrollment.sessionsRemaining,lastCheckIn:r.enrollment.lastCheckIn}:x)}catch(e:any){notify(e.message||'Check-in denied.')}finally{setBusy(false)}};
 const expired=current && (current.status==='expired'||current.expiryDate<today); const low=current && !expired && Number(current.sessionsRemaining)<=2;
 return <div className="space-y-6">
  <div className="grid gap-4 sm:grid-cols-3"><Stat label="Active package holders" value={enrollments.filter(x=>x.status==='active'&&x.expiryDate>=today&&x.sessionsRemaining>0).length}/><Stat label="Low sessions" value={enrollments.filter(x=>x.status==='active'&&x.expiryDate>=today&&x.sessionsRemaining<=2).length} sub="2 or fewer remaining"/><Stat label="Expired / exhausted" value={enrollments.filter(x=>x.status!=='active'||x.expiryDate<today||x.sessionsRemaining<=0).length}/></div>
  <div className="grid gap-6 xl:grid-cols-[360px_1fr]">
   <Card className="p-5"><div className="flex items-center justify-between"><div><p className="text-xs font-black uppercase tracking-widest text-zawana-gold">Package members</p><h2 className="mt-1 text-xl font-black">Check-in desk</h2></div><Button className="px-3 py-2" onClick={()=>{setActionError('');setPurchase(true);setPurchaseStudentId('');setPackageId(packages.find((p:any)=>p.status==='active')?.id||'');setPaymentMethod('Cash')}}><PackagePlus size={15}/> Sell</Button></div>
    <div className="mt-4 flex items-center gap-2 rounded-xl border px-3 py-2"><Search size={16} className="text-zawana-500"/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search student / phone" className="w-full bg-transparent text-sm outline-none"/></div>
    <div className="mt-4 space-y-2">{loading?<p className="p-5 text-sm text-zawana-500">Loading...</p>:filtered.map(x=><button key={x.id} onClick={()=>setSelected(x)} className={`w-full rounded-2xl border p-4 text-left ${current?.id===x.id?'border-zawana-gold bg-zawana-gold/10':'border-zawana-950/8'}`}><div className="flex items-center justify-between"><b>{x.studentName}</b><span className={`rounded-full px-2 py-1 text-[9px] font-black uppercase ${x.status==='active'&&x.expiryDate>=today&&x.sessionsRemaining>0?'bg-emerald-100 text-emerald-700':'bg-red-100 text-red-700'}`}>{x.status==='active'&&x.expiryDate>=today&&x.sessionsRemaining>0?'ACTIVE':'BLOCKED'}</span></div><p className="mt-1 text-xs text-zawana-500">{x.phone} · {x.packageName}</p><div className="mt-3 flex justify-between text-xs"><span>{x.sessionsRemaining}/{x.sessionsTotal} sessions</span><span>Expires {x.expiryDate}</span></div></button>)}{!filtered.length&&<Empty title="No package holder" body="Sell a package to a student or search another name."/>}</div></Card>
   <div className="space-y-6">{!current?<Card className="grid min-h-[360px] place-items-center p-8 text-center"><div><div className="mx-auto grid h-16 w-16 place-items-center rounded-2xl bg-zawana-gold/15"><UserPlus size={26}/></div><h2 className="mt-4 text-2xl font-black">Select a package holder</h2><p className="mt-2 max-w-md text-sm text-zawana-500">Check eligibility before allowing the student onto the court or into a package session.</p></div></Card>:<>
    <Card className={`overflow-hidden p-0 ${expired||Number(current.sessionsRemaining)<=0?'border-2 border-red-500':''}`}><div className={`p-6 text-white ${expired||Number(current.sessionsRemaining)<=0?'bg-red-600':'bg-zawana-950'}`}><div className="flex flex-col gap-5 md:flex-row md:items-center md:justify-between"><div><p className="text-xs font-black uppercase tracking-widest text-white/60">Selected student</p><h2 className="mt-1 text-3xl font-black">{current.studentName}</h2><p className="mt-1 text-sm text-white/60">{current.phone} · {current.packageName}</p></div><div className="flex gap-2"><Button variant="secondary" onClick={()=>{setActionError('');setRenew(true);setPackageId(current.packageId)}}><RotateCcw size={15}/> Renew</Button><Button disabled={busy||!!expired||Number(current.sessionsRemaining)<=0} onClick={checkIn}><Check size={16}/> Check in</Button></div></div></div>
      <div className="grid gap-4 p-6 md:grid-cols-4"><div className="rounded-2xl bg-zawana-950/4 p-4"><p className="text-xs text-zawana-500">Sessions remaining</p><b className="mt-1 block text-2xl">{current.sessionsRemaining}<span className="text-sm font-normal"> / {current.sessionsTotal}</span></b></div><div className="rounded-2xl bg-zawana-950/4 p-4"><p className="text-xs text-zawana-500">Valid until</p><b className="mt-1 block">{current.expiryDate}</b></div><div className="rounded-2xl bg-zawana-950/4 p-4"><p className="text-xs text-zawana-500">Started</p><b className="mt-1 block">{current.startDate}</b></div><div className={`rounded-2xl p-4 ${expired||Number(current.sessionsRemaining)<=0?'bg-red-50 text-red-700':low?'bg-amber-50 text-amber-700':'bg-emerald-50 text-emerald-700'}`}><p className="text-xs opacity-70">Access status</p><b className="mt-1 block">{expired?'EXPIRED':Number(current.sessionsRemaining)<=0?'NO SESSIONS':low?'LOW SESSIONS':'READY TO CHECK IN'}</b></div></div>
      {(expired||Number(current.sessionsRemaining)<=0)&&<div className="mx-6 mb-6 rounded-2xl border border-red-200 bg-red-50 p-4 text-sm text-red-800"><b>Check-in blocked.</b> {expired?'This package has expired.':'This package has no sessions remaining.'} Renew the package before the student can join.</div>}
      {low&&!expired&&Number(current.sessionsRemaining)>0&&<div className="mx-6 mb-6 rounded-2xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-800"><b>Low-session warning.</b> Only {current.sessionsRemaining} session{Number(current.sessionsRemaining)===1?'':'s'} remain. Consider renewing after this visit.</div>}
    </Card>
   </>}</div>
  </div>
  {(purchase||renew)&&<OpsModal title={purchase?'Sell badminton package':'Renew badminton package'} subtitle={purchase?'Activate sessions and validity for this student.':'Replace the current entitlement with a fresh package term.'} onClose={()=>{if(!busy){setPurchase(false);setRenew(false);setActionError('')}}}><div className="grid gap-4">{purchase&&<select className="rounded-xl border p-3" value={purchaseStudentId} onChange={e=>{setPurchaseStudentId(e.target.value);setActionError('')}}><option value="">Select student</option>{o.students.map((s:any)=><option key={s.id} value={s.id}>{s.name} · {s.phone}</option>)}</select>}<select className="rounded-xl border p-3" value={packageId} onChange={e=>{setPackageId(e.target.value);setActionError('')}}><option value="">Select active package</option>{packages.filter(p=>p.status==='active').map(p=><option key={p.id} value={p.id}>{p.title} · {p.sessions} sessions · {p.validity} days · {money(p.price)}</option>)}</select><select className="rounded-xl border p-3" value={paymentMethod} onChange={e=>setPaymentMethod(e.target.value)}><option>Cash</option><option>KPay</option><option>Bank Transfer</option></select>{purchase&&<p className="rounded-xl bg-zawana-950/4 p-4 text-sm text-zawana-500">The package starts today, records the payment in Badminton finance, and immediately controls check-in eligibility.</p>}{!o.students.length&&purchase&&<p className="rounded-xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-800"><b>No students loaded.</b> Refresh the page or create the student first.</p>}{!packages.filter(p=>p.status==='active').length&&<p className="rounded-xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-800"><b>No active packages.</b> Create or activate a badminton package in Package Management first.</p>}{actionError&&<div className="rounded-xl border border-red-200 bg-red-50 p-4 text-sm font-semibold text-red-800"><b>Activation failed:</b> {actionError}</div>}</div><div className="mt-6 flex justify-end gap-2"><Button variant="secondary" disabled={busy} onClick={()=>{setPurchase(false);setRenew(false);setActionError('')}}>Cancel</Button><Button disabled={busy||!packageId||(purchase&&!selectedStudent)||(!purchase&&!current)} onClick={purchase?buy:doRenew}>{busy?(purchase?'Activating...':'Renewing...'):(purchase?'Activate package':'Renew package')}</Button></div></OpsModal>}
 </div>;
}

