function ClinicStats(){const o=useOperations();return <div className="mb-6 grid gap-4 sm:grid-cols-4"><Stat label="Today appointments" value={o.metrics.appointmentsToday}/><Stat label="Pending confirmation" value={o.appointments.filter(a=>a.status==='pending').length}/><Stat label="Checked in" value={o.appointments.filter(a=>a.status==='checked_in').length}/><Stat label="Doctors" value={new Set(o.schedules.filter(s=>s.role==='doctor').map(s=>s.person)).size}/></div>}
function StoreStats(){const o=useOperations();return <div className="mb-6 grid gap-4 sm:grid-cols-4"><Stat label="Products" value={o.products.length}/><Stat label="Low stock" value={o.metrics.lowStock}/><Stat label="Orders" value={o.storeOrders.length}/><Stat label="Revenue" value={money(o.transactions.filter(t=>t.business==='Store').reduce((a,t)=>a+t.finalAmount,0))}/></div>}
function CafeStats(){const o=useOperations();return <div className="mb-6 grid gap-4 sm:grid-cols-4"><Stat label="Open orders" value={o.cafeOrders.filter(x=>!['completed','cancelled'].includes(x.status)).length}/><Stat label="Today sales" value={money(o.transactions.filter(t=>t.business==='Cafe').reduce((a,t)=>a+t.finalAmount,0))}/><Stat label="Pending" value={o.cafeOrders.filter(x=>x.status==='pending').length}/><Stat label="Completed" value={o.cafeOrders.filter(x=>x.status==='completed').length}/></div>}

function BookingQueue({notify}:{notify:(s:string)=>void}){const o=useOperations();return <Table headers={['Customer','Court','Date','Time','Price','Payment','Status','Action']}>{o.courtBookings.map(b=><tr key={b.id}><Cell><b>{b.customer}</b><p className="text-xs text-zawana-500">{b.id}</p></Cell><Cell>{b.court}</Cell><Cell>{b.date}</Cell><Cell>{b.time}</Cell><Cell>{money(b.price)}</Cell><Cell><Badge>{b.paymentStatus}</Badge></Cell><Cell><Badge>{b.status}</Badge></Cell><Cell>{b.status==='pending'?<div className="flex gap-2"><Button className="px-3 py-2" onClick={()=>{o.updateCourtBooking(b.id,'confirmed');notify('Court booking confirmed.')}}><Check size={14}/></Button><Button variant="danger" className="px-3 py-2" onClick={()=>{o.updateCourtBooking(b.id,'cancelled');notify('Booking cancelled.')}}><X size={14}/></Button></div>:<Button variant="secondary" className="px-3 py-2" onClick={()=>{o.updateCourtBooking(b.id,b.status==='confirmed'?'completed':'confirmed');notify('Booking status updated.')}}>Update</Button>}</Cell></tr>)}</Table>}

function BadmintonPackages(){const o=useOperations();return <Table headers={['Package','Sessions','Validity','Price','Status','Actions']}>{o.badmintonPackages.map(p=><tr key={p.id}><Cell><b>{p.title}</b><p className="text-xs text-zawana-500">{p.description}</p></Cell><Cell>{p.sessions}</Cell><Cell>{p.validity} days</Cell><Cell>{money(p.price)}</Cell><Cell><Badge good={p.status==='active'}>{p.status}</Badge></Cell><Cell><div className="flex gap-2"><PackageEdit item={p} kind="badminton"/><PackageDelete id={p.id} name={p.title} kind="badminton"/></div></Cell></tr>)}</Table>}
function PackageEdit({item,kind}:{item:any;kind:'badminton'|'gym'}){const o=useOperations();const [open,setOpen]=useState(false);const [form,setForm]=useState<any>({...item,benefits:Array.isArray(item.benefits)?item.benefits.join(', '):item.benefits||''});const save=async()=>{try{if(kind==='badminton')await o.updateBadmintonPackage(item.id,{title:form.title,price:+form.price,sessions:+form.sessions,validity:+form.validity,description:form.description,status:form.status});else await o.updateGymPackage(item.id,{title:form.title,price:+form.price,duration:+form.duration,description:form.description,benefits:String(form.benefits).split(',').map((x:string)=>x.trim()).filter(Boolean),status:form.status});window.dispatchEvent(new CustomEvent('zawana-toast',{detail:`${kind==='badminton'?'Badminton':'Gym'} package updated.`}));setOpen(false)}catch(e:any){window.dispatchEvent(new CustomEvent('zawana-toast',{detail:e.message||'Update failed.'}))}};return <>{/* eslint-disable-next-line */}<button className="rounded-xl p-2 hover:bg-zawana-900" onClick={()=>setOpen(true)} title="Edit"><Edit3 size={15}/></button>{open&&<OpsModal title={`Edit ${kind} package`} subtitle="Update pricing, validity and status." onClose={()=>setOpen(false)}><div className="grid gap-4 md:grid-cols-2"><label className="space-y-1.5 text-sm"><span className="text-[11px] font-black uppercase tracking-wider text-zawana-500">Title</span><input value={form.title||''} onChange={e=>setForm({...form,title:e.target.value})}/></label><label className="space-y-1.5 text-sm"><span className="text-[11px] font-black uppercase tracking-wider text-zawana-500">Price</span><input type="number" value={form.price??''} onChange={e=>setForm({...form,price:e.target.value})}/></label>{kind==='badminton'?<><label className="space-y-1.5 text-sm"><span className="text-[11px] font-black uppercase tracking-wider text-zawana-500">Sessions</span><input type="number" value={form.sessions??''} onChange={e=>setForm({...form,sessions:e.target.value})}/></label><label className="space-y-1.5 text-sm"><span className="text-[11px] font-black uppercase tracking-wider text-zawana-500">Validity days</span><input type="number" value={form.validity??''} onChange={e=>setForm({...form,validity:e.target.value})}/></label></>:<><label className="space-y-1.5 text-sm"><span className="text-[11px] font-black uppercase tracking-wider text-zawana-500">Duration days</span><input type="number" value={form.duration??''} onChange={e=>setForm({...form,duration:e.target.value})}/></label><label className="space-y-1.5 text-sm"><span className="text-[11px] font-black uppercase tracking-wider text-zawana-500">Benefits</span><input value={form.benefits||''} onChange={e=>setForm({...form,benefits:e.target.value})}/></label></>}<label className="space-y-1.5 text-sm md:col-span-2"><span className="text-[11px] font-black uppercase tracking-wider text-zawana-500">Description</span><textarea value={form.description||''} onChange={e=>setForm({...form,description:e.target.value})}/></label><label className="space-y-1.5 text-sm"><span className="text-[11px] font-black uppercase tracking-wider text-zawana-500">Status</span><select value={form.status||'active'} onChange={e=>setForm({...form,status:e.target.value})}><option value="active">Active</option><option value="inactive">Inactive</option></select></label></div><div className="mt-6 flex justify-end gap-2"><Button variant="secondary" onClick={()=>setOpen(false)}>Cancel</Button><Button onClick={save}><Check size={15}/> Save changes</Button></div></OpsModal>}</>}
function PackageDelete({id,name,kind}:{id:string;name:string;kind:'badminton'|'gym'}){const o=useOperations();const [open,setOpen]=useState(false);const remove=async()=>{try{if(kind==='badminton')await o.deleteBadmintonPackage(id);else await o.deleteGymPackage(id);window.dispatchEvent(new CustomEvent('zawana-toast',{detail:`${name} deleted.`}));setOpen(false)}catch(e:any){window.dispatchEvent(new CustomEvent('zawana-toast',{detail:e.message||'Delete failed.'}))}};return <>{<button className="rounded-xl p-2 text-red-600 hover:bg-red-50" onClick={()=>setOpen(true)} title="Delete"><Trash2 size={15}/></button>}{open&&<ConfirmDelete name={name} onCancel={()=>setOpen(false)} onConfirm={remove}/>}</>}

function PackageManager({kind,showForm,setShowForm,notify}:{kind:'badminton'|'gym';showForm:boolean;setShowForm:(x:boolean)=>void;notify:(s:string)=>void}){const o=useOperations();const [name,setName]=useState('');const [price,setPrice]=useState('');const [number,setNumber]=useState('30');const [validity,setValidity]=useState('60');const [description,setDescription]=useState('');const [benefits,setBenefits]=useState('Gym access');const save=async()=>{if(!name||!price){notify('Please enter a package title and price.');return}try{if(kind==='badminton')await o.addBadmintonPackage({title:name,price:+price,sessions:+number,validity:+validity,description:description||'Custom package',status:'active'});else await o.addGymPackage({title:name,price:+price,duration:+number,description:description||'Custom gym package',benefits:benefits.split(',').map(x=>x.trim()).filter(Boolean),status:'active'});setName('');setPrice('');setNumber('30');setValidity('60');setDescription('');setBenefits('Gym access');setShowForm(false);notify(`${kind==='badminton'?'Badminton':'Gym'} package created.`)}catch(e:any){notify(e.message||'Could not save package.')}};return <div><div className="mb-4 flex justify-end"><Button onClick={()=>setShowForm(true)}><Plus size={16}/> New package</Button></div>{showForm&&<OpsModal title={`Create ${kind} package`} subtitle="Set the package data used by front office and POS." onClose={()=>setShowForm(false)}><div className="grid gap-4 md:grid-cols-2"><input placeholder="Package title" value={name} onChange={e=>setName(e.target.value)}/><input type="number" placeholder="Price" value={price} onChange={e=>setPrice(e.target.value)}/>{kind==='badminton'?<><input type="number" placeholder="Sessions" value={number} onChange={e=>setNumber(e.target.value)}/><input type="number" placeholder="Validity days" value={validity} onChange={e=>setValidity(e.target.value)}/></>:<><input type="number" placeholder="Duration days" value={number} onChange={e=>setNumber(e.target.value)}/><input placeholder="Benefits, separated by comma" value={benefits} onChange={e=>setBenefits(e.target.value)}/></>}<textarea className="md:col-span-2" placeholder="Description" value={description} onChange={e=>setDescription(e.target.value)}/></div><div className="mt-6 flex justify-end gap-2"><Button variant="secondary" onClick={()=>setShowForm(false)}>Cancel</Button><Button onClick={save}><Plus size={15}/> Create</Button></div></OpsModal>}{kind==='badminton'?<BadmintonPackages/>:<GymMemberships/>}</div>}

function GymMemberships(){const o=useOperations();return <Table headers={['Package','Price','Duration','Benefits','Status','Actions']}>{o.gymPackages.map(p=><tr key={p.id}><Cell><b>{p.title}</b><p className="text-xs text-zawana-500">{p.description}</p></Cell><Cell>{money(p.price)}</Cell><Cell>{p.duration} days</Cell><Cell>{p.benefits.join(' · ')}</Cell><Cell><Badge good={p.status==='active'}>{p.status}</Badge></Cell><Cell><div className="flex gap-2"><PackageEdit item={p} kind="gym"/><PackageDelete id={p.id} name={p.title} kind="gym"/></div></Cell></tr>)}</Table>}

function MembershipTable({query,setQuery,notify}:{query:string;setQuery:(x:string)=>void;notify:(s:string)=>void}){const o=useOperations();const rows=o.memberships.filter(m=>[m.customer,m.phone,m.id].some(v=>v.toLowerCase().includes(query.toLowerCase())));return <div><div className="mb-4 flex gap-3"><div className="relative flex-1"><Search className="absolute left-3 top-3.5 text-zawana-400" size={16}/><input className="w-full rounded-xl border p-3 pl-10" placeholder="Search customer, phone or membership ID" value={query} onChange={e=>setQuery(e.target.value)}/></div><Button variant="secondary" onClick={()=>notify('Member creation form is ready for the front desk.') }><UserPlus size={16}/> New member</Button></div><Table headers={['Customer','Package','Start','Expiry','Status','Last check-in','Action']}>{rows.map(m=><tr key={m.id}><Cell><b>{m.customer}</b><p className="text-xs text-zawana-500">{m.phone}</p></Cell><Cell>{m.package}</Cell><Cell>{m.startDate}</Cell><Cell>{m.expiryDate}</Cell><Cell><Badge good>{m.status}</Badge></Cell><Cell>{m.lastCheckIn||'—'}</Cell><Cell><Button className="px-3 py-2" onClick={()=>notify(`${m.customer} checked in.`)}>Check in</Button></Cell></tr>)}</Table></div>}
function GymCheckInWorkflow({query,setQuery,notify}:{query:string;setQuery:(x:string)=>void;notify:(s:string)=>void}){return <Card className="p-6"><div className="mb-5"><h2 className="text-xl font-black">Search → Validate → Check In</h2><p className="text-sm text-zawana-500">Membership status and expiry are validated before attendance is recorded.</p></div><MembershipTable query={query} setQuery={setQuery} notify={notify}/></Card>}

